mapper.select:
SELECT ah.* ,(income_sum-outcome_sum-send_sum+receive_sum) AS balance FROM (
SELECT history_num ,account_num ,your_account_num ,history_date ,income ,outcome ,send ,receive ,nvl(income_sum,0) AS income_sum ,nvl(outcome_sum,0) AS outcome_sum ,nvl(send_sum,0) AS send_sum ,nvl(receive_sum,0) AS receive_sum
FROM (
SELECT history_num,account_num,your_account_num,history_date ,nvl(income,0) AS income,nvl(outcome,0) AS outcome,nvl(send,0) AS send,nvl(receive,0) AS receive ,sum(income) OVER (ORDER BY history_num) AS income_sum ,sum(outcome) OVER (ORDER BY history_num) AS outcome_sum ,sum (send) OVER (ORDER BY history_num) AS send_sum ,sum(receive) OVER (ORDER BY history_num) AS receive_sum FROM ( SELECT * FROM (
SELECT HISTORY_NUM ,ACCOUNT_NUM ,YOUR_ACCOUNT_NUM ,money ,HISTORY_DATE , HISTORY_TYPE FROM ACCOUNT_HISTORY_KOM ah WHERE ACCO
UNT_NUM = #{account_num}
UNION SELECT HISTORY_NUM ,ACCOUNT_NUM ,YOUR_ACCOUNT_NUM ,MONEY ,HISTORY_DATE , '4' AS HISTORY_TYPE FROM ACCOUNT_HISTORY_KOM ah WHERE YOUR_ACCOUNT_NUM = #{account_num} AND ACCOUNT_NUM != YOUR_ACCOUNT_NUM
) pivot ( sum(money) FOR history_type IN (1 AS income,2 AS outcome,3 AS send, 4 AS receive)) ORDER BY history_num asc )
) ) t1, account_history_kom ah WHERE ah.history_num = t1.history_num ORDER BY ah.history_num desc OFFSET (#{page}-1)*10 ROWS FETCH NEXT 10 ROWS ONLY

SELECT COUNT(*)
  FROM account_history_kom
 WHERE account_num = #{account_num}
